package com.bank.batch.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Counts continuous stretches whose net total is divisible by the settlement unit k.
public class BatchDivisibilityCounter {
    private static final Logger log = Logger.getLogger(BatchDivisibilityCounter.class.getName());

    public int countDivisibleStretches(int[] flows, int k) {
        if (flows == null || flows.length == 0 || k <= 0) {
            return 0;
        }
        int[] remainderCounts = new int[k];
        remainderCounts[0] = 1; // empty prefix: enables stretches starting at index 0
        long prefix = 0;
        int count = 0;

        for (int i = 0; i < flows.length; i++) {
            prefix += flows[i];
            // Normalize to a non-negative remainder (Java % can be negative).
            int r = (int) (((prefix % k) + k) % k);
            int add = remainderCounts[r];
            if (add > 0) {
                final int idx = i, a = add, rr = r;
                log.fine(() -> "Day " + idx + ": remainder " + rr + " seen " + a
                        + " time(s) before → " + a + " divisible stretch(es)");
            }
            count += add;
            remainderCounts[r]++;
        }
        final int result = count;
        log.info(() -> "Divisible stretches (unit " + k + ") over "
                + Arrays.toString(flows) + " = " + result);
        return count;
    }
}
