package com.bank.batch;

import com.bank.batch.model.Account;
import com.bank.batch.service.BatchDivisibilityCounter;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SubarraysDivisibleByKDemo {
    private static final Logger log = Logger.getLogger(SubarraysDivisibleByKDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        BatchDivisibilityCounter counter = new BatchDivisibilityCounter();
        int k = 5;

        int[] rajeshFlows = {4, 5, 0, -2, -3, 1}; // classic LeetCode example → 7
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId() + ") flows");
        int r1 = counter.countDivisibleStretches(rajeshFlows, k);
        log.info(() -> rajesh.getHolderName() + " divisible stretches = " + r1);

        int[] priyaFlows = {5, 10, 15}; // every prefix divisible → many stretches
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId() + ") flows");
        int r2 = counter.countDivisibleStretches(priyaFlows, k);
        log.info(() -> priya.getHolderName() + " divisible stretches = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
